insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('d106e7e8-a807-4592-91ca-a5174dfcdf32', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$inleiding: onderzoek naar een kwart eeuw ontwikkeling van flora en fauna in de Oostvaardersplassen$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context1.png$$,
   $$De Oostvaardersplassen, waar de film ‘De nieuwe wildernis’ werd opgenomen, zijn met zo’n 5000 ha een van de grootste natuurgebieden van Nederland. Onderzoeker Perry Cornelissen heeft onderzocht hoe de flora en fauna zich hier in een kwart eeuw ontwikkelden.$$, 'inline'),
  ('347b53bc-a73c-4996-828f-f23cd3945ea1', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$ontstaan van de Oostvaardersplassen en uitzetten van grote grazers (afbeelding 1)$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context2.png$$,
   $$De Oostvaardersplassen liggen in de Flevopolder, die in 1968 werd drooggemalen. In het gebied ontstond op de laagste plek spontaan een rietmoeras van 3600 ha (afbeelding 1). Begin jaren tachtig van de vorige eeuw werd het inmiddels omheinde natuurgebied uitgebreid met een hoger gelegen gebied van zo’n 2400 ha. Populaties van grote grazers zoals edelherten, heckrunderen en konikpaarden die in het gebied zijn uitgezet, konden zich er zonder menselijk ingrijpen ontwikkelen.
afbeelding 1: luchtfoto van de Oostvaardersplassen met rietmoeras, water en grote grazers in het gebied.$$, 'inline'),
  ('9f84554e-e9bb-41c9-8330-b7eeaf150c7c', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$de grote grazers beïnvloedden de successie; is deze natuurlijk verlopen?$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context3.png$$,
   $$De grote grazers hebben invloed gehad op de ontwikkeling van de samenstelling van de flora en fauna in het natuurgebied. De vraag is in hoeverre de successie in de Oostvaardersplassen natuurlijk is verlopen.$$, 'inline'),
  ('20787426-2238-459a-8b11-f4e10a611fa2', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$populatieontwikkeling van heckrunderen, konikpaarden en edelherten sinds begin jaren tachtig (afbeelding 2)$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context4.png$$,
   $$Vanaf begin jaren tachtig zijn 32 heckrunderen, 18 konikpaarden en 52 edelherten in het gebied uitgezet. De populatieontwikkeling wordt sinds die tijd gevolgd (afbeelding 2).
afbeelding 2: grafiek van het aantal dieren (N) tegen het jaar (1983-2016) voor edelhert, konikpaard en heckrund; de aantallen van vooral het edelhert en konikpaard stijgen sterk in de loop van de jaren, het heckrund blijft relatief laag.$$, 'inline'),
  ('1c8f6dea-367b-44c2-8907-ed0a11c7b285', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$vier factoren die de populatiegrootte van grote grazers beïnvloeden$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context5.png$$,
   $$De fluctuaties in populatiegroottes van de grote grazers worden door verschillende factoren beïnvloed. Sommige factoren zijn afhankelijk van de populatiedichtheid, andere niet.
Vier factoren zijn:
1 de beschikbaarheid van voedsel
2 de verspreiding van een besmettelijke ziekte
3 een hoge waterstand
4 een zeer koude winter$$, 'inline'),
  ('74c19e5d-03cb-4198-ba47-1c9edd8a9a75', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$het landschap is minder gevarieerd geworden dan verwacht: vooral kort grasland$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context6.png$$,
   $$Het landschap dat zich in een kwart eeuw heeft ontwikkeld, is minder gevarieerd geworden dan de natuurbeheerders hadden verwacht. In plaats van een afwisselende begroeiing van grasland met hier en daar bosjes met doornstruiken, kruiden en jonge bomen, is er voornamelijk grasland met kort gras ontstaan.$$, 'inline'),
  ('12f9f8db-bb04-4e11-8d18-0c9a1dc13bd8', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$de hoge begrazingsdruk verklaart dit landschapspatroon$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context7.png$$,
   $$Volgens Cornelissen is dit te verklaren door de hoge begrazingsdruk.$$, 'inline'),
  ('a1c9614b-f8c5-4b4b-a2f3-8b236fb230f5', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$geboorte- en sterftecijfers van de grazers in relatie tot graslengte in augustus (afbeelding 3)$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context8.png$$,
   $$In het onderzoek van Cornelissen zijn de jaarlijkse geboorte- en sterftecijfers van verschillende grazers in relatie gebracht met de hoogte van het gras in augustus. Diagram 1 in afbeelding 3 geeft de resultaten weer van de konikpaarden. Diagram 2 en 3 geven de resultaten weer van de twee andere grote grazers.
afbeelding 3: drie diagrammen (1, 2 en 3) van het percentage geboorte en sterfte tegen de lengte van de grasschede in augustus (cm), elk met een geboortelijn (stijgend) en een sterftelijn (dalend) die elkaar kruisen in het evenwichtspunt R*; diagram 1 toont de gegevens van de konikpaarden, diagram 2 en 3 tonen de gegevens van de twee andere grote grazers (heckrund en edelhert, in willekeurige volgorde) en hebben een hogere R*-waarde dan diagram 1.$$, 'inline'),
  ('942c46a4-5aae-4e8b-9d68-6509a58c9fd8', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$de lage R*-waarde bij konikpaarden; twee gegevens over hun voedsel$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context9.png$$,
   $$De graslengte waarbij geboorte en sterfte in de populatie in evenwicht zijn (R*) ligt bij de konikpaarden veel dichter bij nul dan bij de andere grazers. Twee gegevens over het voedsel van de paarden en van de andere grazers zijn:
1 Paarden kunnen zeer kort gras eten, de andere grote grazers niet.
2 Paarden eten bij afwezigheid van voldoende gras ook wortels van brandnetel en riet, de andere grote grazers niet.$$, 'inline'),
  ('24a0060d-681e-41d6-9c5d-e4d1119b7a72', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$niet vermeld welk diagram bij heckrunderen en welk bij edelherten hoort$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context10.png$$,
   $$Bij diagram 2 en 3 in afbeelding 3 staat niet vermeld welk diagram gegevens van heckrunderen en welk diagram gegevens van edelherten weergeeft. Met behulp van de gegevens over de populatieontwikkeling (afbeelding 2, pagina 3) is dat af te leiden.$$, 'inline'),
  ('c4e36461-fdd3-4deb-b3fe-3c34354f9988', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$de dichtheid van grote grazers moet omlaag voor meer biodiversiteit$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context11.png$$,
   $$Cornelissen heeft berekend dat de dichtheid van grote grazers moet verminderen van 1,1 per hectare naar ongeveer 0,2 per hectare om een grotere biodiversiteit te bereiken.$$, 'inline'),
  ('c753bf65-b8f4-471e-b8a4-83e5408e779f', '0014c61f-f4bc-4a21-a121-ae0d4765a089', $$afschieten en verplaatsen van grazers zijn geen opties$$,
   $$biologie-vwo-2019-ii-hoe-wild-blijft-de-nieuwe-wildernis-context12.png$$,
   $$Jaarlijks grote grazers afschieten past niet in het oorspronkelijke beheer en de grazers kunnen ook niet elders in Nederland terecht.$$, 'inline'),
  ('2ba29d17-0b0f-4ec9-bce6-6678b1c7bb78', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$inleiding: RNAi als nieuwe bestrijdingstechniek tegen de Coloradokever$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context1.png$$,
   $$De insecten die een bedreiging vormen voor voedselgewassen worden steeds meer resistent tegen insecticiden. Een nieuwe bestrijdingstechniek maakt gebruik van RNAi (RNA-interferentie). Het is onderzoekers van het Max Planck Instituut gelukt om hiermee de Coloradokever, wereldwijd de grootste bedreiger van de aardappeloogst, uit te schakelen.$$, 'inline'),
  ('5158dd9b-b65e-4f4e-bc79-aa3c5cc1db8a', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$de Coloradokever is resistent tegen insecticiden, waaronder neonicotinoïden (afbeelding 1)$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context2.png$$,
   $$De Coloradokever (Leptinotarsa decemlineata, afbeelding 1) werd in 1922 per ongeluk vanuit de VS geïntroduceerd in Europa. Ook in Nederland vinden de kever en zijn larven een overmaat aan voedsel. Ze eten bladeren van de aardappel en verwante soorten zoals de tomaat, en hebben weinig last van natuurlijke vijanden. Coloradokevers hebben resistentie ontwikkeld tegen verschillende veelgebruikte insecticiden en inmiddels ook tegen de nieuwere middelen uit de groep van de neonicotinoïden.
afbeelding 1: foto van een Coloradokever op een aardappelblad.$$, 'inline'),
  ('3bbcbfc2-1229-4053-b461-1051de959be7', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$veredeling vermindert vaak de chemische afweer van voedselgewassen tegen vraat$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context3.png$$,
   $$Wilde planten beschikken vaak over hun eigen chemische bescherming tegen vraat. Bij het ontwikkelen van voedselgewassen is deze bescherming door de veredeling vaak verminderd.$$, 'inline'),
  ('f13a1ccb-c3f8-4990-b344-95f68cae0efd', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$neonicotinoïden blokkeren acetylcholinereceptoren in het zenuwstelsel van insecten$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context4.png$$,
   $$Insecticiden uit de groep van neonicotinoïden blokkeren de acetylcholine-receptoren in het centrale zenuwstelsel van insecten.$$, 'inline'),
  ('ea97897d-b80a-4ca6-88f4-c21a9086b8fa', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$het RNAi-mechanisme tegen het ACT-gen van de Coloradokever (afbeelding 2)$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context5.png$$,
   $$De onderzoekers maakten met behulp van DNA-technieken aardappelplanten die dubbelstrengs-RNA (dsRNA) konden produceren gericht tegen het ACT-gen van de Coloradokever. Het ACT-gen codeert voor β-actine, een belangrijk onderdeel van het cytoskelet van cellen van de kever. Het dsRNA van de aardappelplant kan in de cellen van de kever het mechanisme van RNAi in gang zetten waardoor de genexpressie van het ACT-gen wordt geremd.
RNAi werkt als volgt (afbeelding 2):
1 dsRNA wordt in het cytoplasma door het enzym dicer geknipt in stukjes van ongeveer 21 nucleotiden, die siRNA (short interfering RNA) worden genoemd.
2 De antisense-streng van het siRNA vormt vervolgens, samen met een complex van eiwitten, het RISC (RNA-induced silencing complex).
3 Zodra RISC een mRNA met een complementaire code bindt, wordt dit mRNA vernietigd.
afbeelding 2: schema van dsRNA dat door het enzym dicer wordt geknipt tot siRNA-stukjes (stap 1); de antisense-RNA-streng vormt met RISC-eiwitten het RISC-complex (stap 2), dat een complementair mRNA bindt en vernietigt (stap 3).$$, 'inline'),
  ('ce2c1e55-e518-4952-ba76-08e83972ce01', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$het dsRNA is gericht tegen een deel van een exon in het ACT-gen$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context6.png$$,
   $$Het dsRNA van de aardappelplant is gericht tegen een deel van een exon in het ACT-gen.$$, 'inline'),
  ('c667a855-92f8-466c-9a6d-708b79a681b5', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$RNAi-mechanisme bij genconstruct in chloroplasten versus in de celkern (afbeelding 3)$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context7.png$$,
   $$De onderzoekers maakten twee typen transgene planten: aardappelplanten waarbij het genconstruct voor het maken van dsRNA gericht tegen het ACT-gen was ingebouwd in de chloroplasten en aardappelplanten waarbij het genconstruct was ingebouwd in de celkern. Er bleek een groot verschil in overleving wanneer de kevers en hun larven van het ene type plant aten of van het andere type plant. Het veronderstelde RNAi-mechanisme en de gevolgen voor de kevers is vereenvoudigd weergegeven in afbeelding 3.
afbeelding 3: schema van twee methoden: methode 1 (genconstruct in chloroplast-DNA) waarbij in de plantencel dsRNA in het cytoplasma wordt gevormd en na opname door de kever in de darm door dicer tot siRNA wordt geknipt, waarna de kever sterft; methode 2 (genconstruct in kern-DNA) waarbij dicer al in de plantencel dsRNA tot siRNA knipt, zodat alleen siRNA (en geen dsRNA) in de darm van de kever terechtkomt, waarna de kever overleeft.$$, 'inline'),
  ('fcda8e7e-6c31-432e-aca0-a4d1a4526751', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$de RNAi-techniek heeft een groter effect op larven dan op volwassen kevers$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context8.png$$,
   $$De beschreven RNAi-techniek gericht tegen het ACT-gen heeft een groter effect op de larven van insecten dan op volwassen exemplaren.$$, 'inline'),
  ('5b269b6a-439b-49ee-9249-1a28e712588a', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$insectenbestrijding met RNAi is selectiever dan met reguliere insecticiden$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context9.png$$,
   $$Insectenbestrijding met RNAi is selectiever dan bestrijding met reguliere insecticiden.$$, 'inline'),
  ('f72006ec-6cbb-4984-9b5a-21430a65f388', 'f1ec6a44-b625-4e37-8f80-3ac24debd936', $$verspreiding van het genconstruct: kern-DNA versus chloroplast-DNA$$,
   $$biologie-vwo-2019-ii-insecten-bestrijden-met-rnai-context10.png$$,
   $$Aardappelplanten worden ongeslachtelijk vermeerderd via knollen (de aardappels). Daarnaast vormt de plant bloemen en vruchten. De vruchtjes worden echter niet rijp omdat aardappels voor die tijd worden geoogst. Bij voedselgewassen waarbij het genconstruct in het kern-DNA is ingebouwd, kan het gebeuren dat het genconstruct zich in de natuur verspreidt en terechtkomt in een nauwverwante soort. In het geval van de transgeen gemaakte chloroplasten is die kans nihil doordat plastiden bij aardappelplanten op dezelfde manier overerven als mitochondriën.$$, 'inline'),
  ('118662fd-b026-4667-b409-33508fe09d83', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$inleiding: Bram (16) is CF-patiënt en wordt multidisciplinair behandeld$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context1.png$$,
   $$Taaislijmziekte of cystic fibrosis (CF) is een ernstige en veelvoorkomende erfelijke aandoening. Doordat de ziekte complex is, wordt de behandeling in Nederlandse CF-centra multidisciplinair aangepakt. Zo ook bij Bram, een CF-patiënt van 16 jaar. Minimaal een keer in de drie maanden bezoekt Bram het CF-centrum voor controle, en jaarlijks vindt een uitgebreid onderzoek plaats.$$, 'inline'),
  ('c2bb1e9d-1b7c-46b1-aa1a-13f3b98b7c3a', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$CF ontstaat door een defect CFTR-gen, waardoor chloridekanalen en taai slijm ontstaan$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context2.png$$,
   $$De basis van CF ligt in een defect in het gen voor het eiwit CFTR. Dit eiwit vormt normaliter een chloridekanaal in het celmembraan van epitheelcellen. Door het gendefect worden geen of slecht werkende chloridekanalen gemaakt. Daardoor is ook het transport van water in alle weefsels met epitheelcellen verstoord. Slijm dat op diverse plaatsen in het lichaam, zoals in de longen, wordt afgescheiden is door deze aandoening abnormaal taai. De defecte chloridekanaaltjes hebben gevolgen voor het functioneren van verschillende organen. Door het taaie slijm raken afvoergangen van organen verstopt, onder andere in het spijsverteringsstelsel.$$, 'inline'),
  ('f3d87f8c-4c48-4e11-9757-395e8f627354', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$CF-patiënten hebben een verhoogd risico op infecties zoals longontsteking$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context3.png$$,
   $$CF-patiënten hebben een verhoogd risico op infecties. Bram heeft hierdoor al een paar keer in het ziekenhuis gelegen met een longontsteking.$$, 'inline'),
  ('c4091a4d-3b5e-492f-88be-7d60884eab5b', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$segregatiebeleid voorkomt kruisbesmetting; P. aeruginosa uit tuinaarde is minder gevaarlijk$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context4.png$$,
   $$Bij een bezoek aan het CF-centrum mag Bram niet in contact komen met andere CF-patiënten. Dit segregatiebeleid voorkomt dat Bram een bacterie oploopt van een andere CF-patiënt. Bacteriën die algemeen voorkomen in bijvoorbeeld tuinaarde, zoals Pseudomonas aeruginosa, veroorzaken bij gezonde mensen zelden problemen, maar kunnen bij CF-patiënten chronische infecties veroorzaken, die met antibiotica behandeld worden.$$, 'inline'),
  ('0ab042bc-d159-464f-887e-d42fc121b0fa', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$alvleessapafgifte is belemmerd; Bram slikt enzymsupplementen$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context5.png$$,
   $$Doordat ook de alvleessapafgifte belemmerd is bij CF-patiënten, is de omzetting van bepaalde bestanddelen in de voeding beperkt. Bram slikt daarom enzymsupplementen, zodat deze omzettingen wel goed kunnen plaatsvinden.$$, 'inline'),
  ('f320b629-374f-488e-a092-0c30bc640cd8', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$drie omzettingen in het darmkanaal van een gezond persoon$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context6.png$$,
   $$Drie omzettingen in het darmkanaal van een gezond persoon zijn:
1 glycogeen → maltose
2 dipeptiden → aminozuren
3 triglyceriden → monoglyceriden$$, 'inline'),
  ('c61d5cb3-07e7-48f5-8891-e4d9c3e1cca3', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$ondanks enzymsupplementen is Brams vetvertering niet optimaal (vettige ontlasting)$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context7.png$$,
   $$De enzymsupplementen die Bram bij elke maaltijd slikt werken goed maar toch is zijn vetvertering niet optimaal: hij heeft een vettige ontlasting.$$, 'inline'),
  ('24e43716-887f-4ec4-9979-6bf63cf1b186', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$verhoogde ruststofwisseling; CO2- en O2-gehalte meten; twee dissimilatiegegevens$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context8.png$$,
   $$Bram moet zijn best doen om niet af te vallen. Net als veel andere CF-patiënten heeft hij een verhoogde ruststofwisseling. De ruststofwisseling kan worden afgeleid uit de meting van het CO₂-gehalte én het O₂-gehalte van de lucht die in- en uitgeademd wordt tijdens rust.
Gegevens met betrekking tot de dissimilatie zijn:
1 In spieren kan anaerobe dissimilatie optreden, waarbij melkzuur wordt gevormd maar geen CO₂.
2 Bij de dissimilatie van eiwitten en vetten wordt meer O₂ verbruikt dan er aan CO₂ wordt gevormd.$$, 'inline'),
  ('1f22185d-a3a8-4b8d-825b-5682a3cfcc3a', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$VO2-max is een maat voor de lichamelijke conditie$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context9.png$$,
   $$De lichamelijke conditie van Bram wordt goed gecontroleerd. Een maat voor de conditie is de VO₂-max: het maximale volume zuurstof dat bij maximale lichamelijke inspanning per tijdseenheid getransporteerd en verbruikt wordt. Hoe hoger de VO₂-max is, hoe beter de conditie is.$$, 'inline'),
  ('55d38274-0efa-4ce0-916d-b7c59419b1c7', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$drie orgaanstelsels beïnvloeden de VO2-max (afbeelding 1)$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context10.png$$,
   $$Drie orgaanstelsels beïnvloeden de VO₂-max. In afbeelding 1 is de samenhang tussen deze drie orgaanstelsels schematisch weergegeven.
afbeelding 1: schema van drie als tandwielen voorgestelde orgaanstelsels (1, 2 en 3) die op elkaar grijpen, met bij tandwiel 1 mitochondriën aangegeven en bij tandwiel 3 de uitwisseling van O₂ en CO₂ met de lucht.$$, 'inline'),
  ('b37e9274-ab39-438d-a1f7-95f9c4caa815', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$vier waarden (r, s, t, u) om de VO2-max te berekenen$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context11.png$$,
   $$De VO₂-max kan worden berekend met de volgende waarden:
− r het O₂-gehalte in aders
− s het O₂-gehalte in slagaders
− t de hartslagfrequentie
− u het slagvolume van het hart$$, 'inline'),
  ('0663ca88-cf9c-46a4-a9b1-0b8d64d1734c', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$VO2-max kan ook via een inspanningstest op de hometrainer bepaald worden$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context12.png$$,
   $$De VO₂-max kan ook afgeleid worden uit een inspanningstest. Bram moet dan zo hard mogelijk fietsen op een hometrainer terwijl de samenstelling van de lucht die hij in- en uitademt voortdurend geregistreerd wordt. De VO₂-max is bereikt als de hoeveelheid zuurstof die Bram opneemt niet meer toeneemt, ondanks een toenemende inspanning.$$, 'inline'),
  ('f3dce2ba-8700-4bf2-8d78-09793fdcb182', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$VO2-max wordt gecorrigeerd voor lichaamsgewicht; CF-kinderen hebben een lage vetmassa$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context13.png$$,
   $$Om het resultaat van de VO₂-max-meting te beoordelen en te vergelijken met dat van andere personen, wordt er doorgaans gecorrigeerd voor het lichaamsgewicht. De uitkomst wordt dan uitgedrukt in het maximale aantal milliliters opgenomen zuurstof per kilogram lichaamsgewicht per minuut. CF-kinderen hebben echter een lager lichaamsgewicht dan normaal door een relatief lage vetmassa. Er moet dus een extra correctie plaatsvinden om de VO₂-max van Bram te kunnen vergelijken met die van gezonde leeftijdsgenoten. Anders geeft de VO₂-max een verkeerde indruk van zijn conditie.$$, 'inline'),
  ('bf1fd648-e4d0-423a-907c-74fc8bd093a4', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$hyperinflatie door herhaalde longinfecties; longparameters restvolume en vitale capaciteit$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context14.png$$,
   $$Herhaalde longinfecties leiden tot schade aan de luchtwegwand. Dit geeft problemen doordat lucht wel makkelijk de longen inkomt, maar er door obstructie niet makkelijk uitgaat. Hierdoor wordt er telkens iets meer lucht ingeademd dan uitgeademd. Het gevolg is ‘hyperinflatie’. Bij elk bezoek aan het CF-centrum wordt de longfunctie van Bram onderzocht en worden de longparameters vergeleken met die van het vorige bezoek.
Twee longparameters zijn:
− het restvolume
− de vitale capaciteit$$, 'inline'),
  ('5aad7ec1-68d6-445a-8c6c-ed73bc77b917', 'b2e97adb-99d2-40f2-9be3-c782b1e70766', $$gentherapie met een intact CFTR-gen verbeterde de longfunctie, maar genas CF niet$$,
   $$biologie-vwo-2019-ii-leven-met-cystic-fibrosis-context15.png$$,
   $$Genezing van CF zou op termijn wellicht mogelijk zijn met behulp van gentherapie. Een methode die is onderzocht, is het inbrengen van een intact CFTR-gen in de epitheelcellen van de luchtwegen van CF-patiënten. Die epitheelcellen gingen vervolgens het juiste CFTR-eiwit produceren. Hoewel de patiënten hierdoor een verbeterde longfunctie kregen, was er geen sprake van genezing van CF.$$, 'inline'),
  ('42a4ddf6-01ab-4908-b773-85c87c12609f', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$inleiding: is er een wetenschappelijke verklaring voor smaakbeleving?$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context1.png$$,
   $$Zijn spruitjes lekker of niet? Over smaak valt niet te twisten zegt men wel, en daar blijkt nu een wetenschappelijke verklaring voor te zijn.$$, 'inline'),
  ('107983df-c6f7-477e-84ae-2d77034dc464', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$smaakzintuigcellen en de signaalcascade bij een bittere stof (afbeelding 1)$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context2.png$$,
   $$Smaakpapillen op de tong bevatten vele smaakzintuigcellen, die samen gevoelig zijn voor de vijf nu bekende smaken: zoet, zuur, zout, bitter en umami. Smaakzintuigcellen zijn chemoreceptoren waarbij elk type op een eigen manier een bepaalde smaak waarneemt.
In afbeelding 1 is weergegeven hoe een bepaalde bittere stof uit spruitjes een smaakzintuigcel activeert: er wordt een signaalcascade in gang gezet die impulsen opwekt in het neuron dat aan de chemoreceptor verbonden is. In de signaalcascade zijn met de nummers 1 tot en met 4 enkele stoffen aangegeven.
afbeelding 1: schema van een smaakzintuigcel met een signaalcascade: de bittere stof bindt aan een receptor (1) in het membraan, waarna via stof 2 (PIP₂) stof 3 (IP₃) wordt gevormd, dat een Ca²⁺-kanaal opent zodat Ca²⁺ het cytoplasma instroomt; stof 4 is de signaalstof die vervolgens bij het neuron vrijkomt.$$, 'inline'),
  ('82c65e64-cf5f-415c-b1a8-440950a605cb', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$de functies van de stoffen 1 tot en met 4: enzym, receptor, second messenger, signaalstof$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context3.png$$,
   $$De functies van de stoffen 1 tot en met 4 (afbeelding 1) zijn:
− enzym
− receptor
− second messenger
− signaalstof$$, 'inline'),
  ('80ccdff2-e92e-4a41-bf55-ce0922a7fb1f', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$de signaalcascade verhoogt de Ca2+-concentratie en leidt tot impulsen in het neuron$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context4.png$$,
   $$De signaalcascade in de smaakzintuigcel leidt uiteindelijk via een verhoging van de Ca²⁺-concentratie in het cytoplasma tot het ontstaan van impulsen in het aangrenzende neuron.$$, 'inline'),
  ('7c247428-3db8-4437-9501-7e20561e0018', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$de meeste mensen zijn gewone proevers; superproevers hebben meer en gevoeligere smaakzintuigcellen$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context5.png$$,
   $$De meeste mensen zijn ‘gewone’ proevers. Sommige mensen proeven relatief weinig, zij houden van sterke smaken. En andere mensen zijn superproever: zij hebben meer smaakpapillen, met meer smaakzintuigcellen die ook nog gevoeliger zijn.$$, 'inline'),
  ('4ce2ab39-a693-47fe-b8d1-a0b222d15b9b', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$de schrikreflex van superproevers: een tekst met drie ontbrekende woorden over de reflexboog$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context6.png$$,
   $$Superproevers vertonen soms bij het eten van een bittere stof een schrikreflex: ze knijpen de ogen dicht en spannen de nekspieren aan. In het stukje tekst hieronder wordt de betreffende reflexboog beschreven. Op de plaatsen 1, 2 en 3 ontbreekt een woord.
“Informatie van smaakzintuigcellen wordt normaliter verwerkt in de …(1)… van het smaakcentrum in de hersenschors. Een bittere stof kan bij een superproever een reflexboog in gang zetten die via …(2)… leidt tot impulsen in …(3)… neuronen, waardoor de ogen dichtknijpen.”
bij 1: grijze stof / witte stof
bij 2: de hersenstam / het ruggenmerg
bij 3: motorische / sensorische$$, 'inline'),
  ('ba191a99-7291-40a3-b2b8-ff9becb5caa8', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$PTC-proeftest: niet-proevers en superproevers zijn homozygoot voor verschillende allelen$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context7.png$$,
   $$Het proeven van bittere stoffen kan getest worden met behulp van PTC, een bittere smaakstof. Lange tijd werd aangenomen dat het vermogen om PTC te proeven, berust op een enkel autosomaal gen met twee allelen. Niet-proevers zijn homozygoot voor het ene allel, superproevers zijn homozygoot voor het andere allel. Superproevers vinden PTC heel sterk smaken (en vaak ook heel vies). Iemand met het heterozygote genotype kan de stof wel proeven, maar proeft die niet heel sterk.$$, 'inline'),
  ('102c49d7-8148-4342-a0e0-92c58bed8898', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$PTC-vaderschapstest: een moeder die geen superproever is en een dochter die niet proeft$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context8.png$$,
   $$Door deze duidelijke genetische correlatie werd in het verleden het al dan niet proeven van PTC als vaderschapstest gebruikt. Deze test is echter niet altijd eenduidig. Stel dat een moeder PTC waarneemt, maar geen superproever is, en haar dochter de stof niet proeft.$$, 'inline'),
  ('93ea8175-b368-4a42-b8c8-7b612b28e1d5', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$percentage niet-proevers van PTC per werelddeel (afbeelding 2)$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context9.png$$,
   $$In een rapport van het Amerikaanse NIDCD werd het percentage personen dat PTC niet proeft, in verschillende bevolkingsgroepen, landen en werelddelen gepresenteerd. Een deel is in afbeelding 2 weergegeven.
afbeelding 2: puntdiagram met het percentage niet-proevers (met spreiding) voor India, Europa, Afrika en China; mediaanwaarden 32,8% (India), 27,9% (Europa), 16,3% (Afrika) en 13,6% (China).$$, 'inline'),
  ('30fe6178-45a1-4426-990c-12c4a9e6711a', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$mogelijk selectievoordeel voor het intermediaire fenotype$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context10.png$$,
   $$Als er een sterk selectienadeel zou zijn voor het fenotype superproever of niet-proever, zou je verwachten dat een van beide allelen door natuurlijke selectie verdwenen zou zijn. Sommige wetenschappers denken daarom dat er een selectievoordeel is voor het intermediaire fenotype.$$, 'inline'),
  ('1ac55060-d314-419c-85a1-f5455600bd28', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$het genetisch mechanisme is complexer: meerdere genen, allelen en SNP’s bepalen de smaak$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context11.png$$,
   $$Het genetisch mechanisme voor het proeven van bittere stoffen blijkt complexer dan in eerste instantie werd gedacht. Waarschijnlijk zijn er meer genen bij betrokken. Bovendien kunnen er per gen meerdere allelen zijn. Hierdoor is er een grote variatie in receptoreiwitten voor de verschillende bittere stoffen. De smaak van bijvoorbeeld spruitjes kan hierdoor zeer verschillend worden waargenomen.
Soms verschillen de allelen van één gen als gevolg van slechts één veranderd basenpaar. Een dergelijk SNP (single nucleotide polymorphism) kan leiden tot een niet-functioneel of een anderswerkend eiwit.$$, 'inline'),
  ('81b4a664-3702-4708-b7e3-24d7ab042868', 'e428084c-87d3-479e-ae20-e0eedbcfa47c', $$een SNP leidt tot een afwijkend eiwit en daardoor een andere smaakwaardering$$,
   $$biologie-vwo-2019-ii-zijn-bittere-spruitjes-lekker-context12.png$$,
   $$Een bepaald SNP leidt op moleculair niveau tot de vorming van een afwijkend eiwit, dat op niveau van het organisme een andere smaakwaardering tot gevolg heeft.$$, 'inline'),
  ('a7c6c8e5-f7d3-49d8-8028-1eb4a5289b2e', '65823294-d973-49fd-a342-a7e2a145fbee', $$inleiding: dalende vaccinatiegraad terwijl mazelen geen onschuldige kinderziekte is$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context1.png$$,
   $$Steeds meer ouders in Europese steden zien af van vaccinatie van hun kinderen, waardoor mazelenepidemieën steeds vaker zullen optreden. Mazelen is echter geen onschuldige kinderziekte.$$, 'inline'),
  ('edb29de9-2be1-42a0-8ab5-70d899949746', '65823294-d973-49fd-a342-a7e2a145fbee', $$het mazelenvirus verspreidt zich via macrofagen/lymfocyten en wist het immunologisch geheugen$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context2.png$$,
   $$Mazelen is een zeer besmettelijke virusziekte die het immuunsysteem langdurig verzwakt. Het virus wordt verspreid via de lucht door hoesten, niezen en praten. Eenmaal in de luchtwegen infecteert het virus een macrofaag of een dendritische cel die het virus naar het lymfesysteem vervoert, waar het vermenigvuldigd wordt in lymfocyten. Vanuit de lymfocyten komt het virus terecht in andere lichaamscellen, zoals die van de huid, wat te zien is aan de rode uitslag. Het kan ook cellen van de longen, lever en blaas en soms van de hersenen infecteren.
Het grootste gevaar is dat door de ziekte het immunologisch geheugen van het lichaam grotendeels wordt gewist. Tot wel drie jaar later is hierdoor de kans op secundaire infecties, zoals een bacteriële longontsteking, veel groter.$$, 'inline'),
  ('3624f455-2ff9-4498-8c67-07ffd76fe308', '65823294-d973-49fd-a342-a7e2a145fbee', $$route van een geïnfecteerde macrofaag naar de lokale lymfeknoop en de milt$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context3.png$$,
   $$Iemand ademt een mazelenvirus in en dit virus infecteert een macrofaag in de luchtwegen. Virusdeeltjes uit de macrofaag infecteren op hun beurt de lymfocyten in een lokale lymfeknoop. Via de lymfocyten bereikt het virus cellen in de milt.$$, 'inline'),
  ('9e1f1d10-a49f-40ba-91ea-2471c74d1e95', '65823294-d973-49fd-a342-a7e2a145fbee', $$het levend verzwakte mazelenvaccin en de bouw van het mazelenvirus (afbeelding 1)$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context4.png$$,
   $$Sinds 1963 is er een ‘levend’ vaccin tegen mazelen. Dit vaccin bevat mazelenvirussen die verzwakt zijn doordat het virus herhaaldelijk is gerepliceerd in verschillende celculturen: in menselijke niercellen en amnioncellen, en daarna in cellen van kippenembryo’s. De verzwakte virussen die zo ontstaan, wekken een goede immuunreactie op, maar worden veel minder vaak vermenigvuldigd en minder verspreid in menselijke gastheercellen. Je wordt daardoor niet tot nauwelijks ziek van het vaccin.
In afbeelding 1 is het mazelenvirus schematisch weergegeven.
afbeelding 1: schema van het mazelenvirus met een omhullend membraan waarin H-eiwit en F-eiwit zitten, en daarbinnen RNA met L-eiwit.
Het virale genoom van het mazelenvirus bestaat uit RNA dat onder andere codeert voor de volgende structuureiwitten:
− H-eiwit (hemagglutinine): voor hechting aan de gastheercel
− F-eiwit (fusie-eiwit): voor fusie van het virus met de gastheercel
− L-eiwit (large protein): enzymatisch deel van het RNA-polymerase-complex$$, 'inline'),
  ('824379f4-807b-4953-b9b6-a725cb3a3d3d', '65823294-d973-49fd-a342-a7e2a145fbee', $$twee immuunresponsen: rijping van cytotoxische T-cellen en van plasmacellen$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context5.png$$,
   $$De immuunrespons die opgewekt wordt door verzwakte virussen in een ‘levend’ vaccin is anders dan de immuunrespons die opgewekt wordt door virusdelen in een ‘dood’ vaccin.
Twee immuunresponsen zijn:
1 rijping van cytotoxische T-cellen
2 rijping van plasmacellen$$, 'inline'),
  ('a9dcee84-e6ae-4488-a83d-121905493ddb', '65823294-d973-49fd-a342-a7e2a145fbee', $$baby’s jonger dan vier weken worden niet gevaccineerd; het vaccin slaat niet aan$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context6.png$$,
   $$Baby’s jonger dan vier weken worden niet gevaccineerd en de eerste vaccinatie tegen mazelen komt pas na een jaar. Heel jonge baby’s vaccineren heeft over het algemeen geen nut: het vaccin slaat niet aan. Dit is gedeeltelijk te wijten aan het onvoldoende uitgerijpte immuunsysteem.$$, 'inline'),
  ('5fb04680-000d-4918-be4c-25c30a606d84', '65823294-d973-49fd-a342-a7e2a145fbee', $$een geboortecohort van 200.000 kinderen, 93% gevaccineerd met 92% effectieve bescherming$$,
   $$biologie-vwo-2019-ii-vaccineren-tegen-mazelen-context7.png$$,
   $$Door tegenstanders van vaccinatie wordt soms het argument gebruikt dat bij een mazelenepidemie meer gevaccineerde kinderen de ziekte krijgen dan niet-gevaccineerde kinderen.
Ga uit van een geboortecohort (jaargroep) van 200.000 kinderen. Van deze kinderen wordt 93% gevaccineerd en het vaccin geeft in 92% van de toedieningen een effectieve bescherming tegen mazelen.$$, 'inline');

